def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        if supply >= 22:
            return float(min(budget, DAILY_SALARY * 0.18))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if float(opp.get('budget', 0)) > budget:
            rich_opp += 1
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 3:
            urgent_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = 1.0 - ((supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY))
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    emergency = (hp <= 2) or (no_water_days >= 2)
    pressured = (hp <= 4) or (no_water_days >= 1)

    if emergency:
        base = max(DAILY_SALARY * 0.95, avg_prev + 8.0, highest_prev * 0.86)
        if supply <= 17:
            base = max(base, highest_prev + 2.0, 118.0)
        return float(max(0.0, min(budget, base)))

    if pressured:
        base = DAILY_SALARY * (0.72 + 0.28 * scarcity)
        if highest_prev > 0:
            base = max(base, avg_prev * 0.9, highest_prev * 0.78)
        if urgent_opp >= 2:
            base += 8.0
        if supply <= 17:
            base += 10.0
        return float(max(0.0, min(budget, base)))

    if supply >= 23:
        base = DAILY_SALARY * 0.22
    elif supply >= 20:
        base = DAILY_SALARY * 0.34
    elif supply >= 18:
        base = DAILY_SALARY * 0.48
    else:
        base = DAILY_SALARY * 0.62

    if highest_prev >= 150:
        if supply >= 20 and hp >= 6:
            base = min(base, DAILY_SALARY * 0.28)
        else:
            base = max(base, DAILY_SALARY * 0.7)
    elif highest_prev >= 105:
        if supply >= 21 and hp >= 7:
            base = min(base, DAILY_SALARY * 0.3)
        else:
            base = max(base, avg_prev * 0.72)
    elif highest_prev > 0:
        base = max(base, avg_prev * 0.82)

    if urgent_opp >= 2 and supply <= 18:
        base += 7.0
    if rich_opp >= 2 and supply >= 21 and hp >= 7:
        base -= 4.0
    if day >= 8 and hp >= 7 and no_water_days == 0 and supply >= 20:
        base -= 5.0

    if base < 0:
        base = 0.0
    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    is_scarce = current_supply < total_water_needed

    base_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.75
    elif my_hp >= 8:
        base_bid = DAILY_SALARY * 0.4

    if is_scarce:
        base_bid *= 1.2
        if my_hp <= 3:
            base_bid = DAILY_SALARY * 0.95

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace')
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if max_yesterday_bid > DAILY_SALARY * 0.7:
            if my_hp <= 3:
                base_bid = max(base_bid, max_yesterday_bid + 5)
            else:
                base_bid = max(base_bid, avg_yesterday_bid * 1.05)
        elif max_yesterday_bid < DAILY_SALARY * 0.3:
            if my_hp >= 8:
                base_bid = min(base_bid, avg_yesterday_bid + 5)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.4)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_hp <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)
    if remaining_days == 1 and my_hp <= 2:
        base_bid = DAILY_SALARY * 0.99

    calculated_bid = base_bid

    if my_no_water_days > 0:
        calculated_bid = max(calculated_bid, DAILY_SALARY * 1.1)

    final_bid = min(my_budget, calculated_bid)

    if final_bid < 1 and my_budget >= 1:
        final_bid = 1
    elif final_bid < 1 and my_budget < 1:
        final_bid = my_budget

    return round(final_bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
